import{_ as r,a0 as i,w as h,s as l,ao as c,I as p,x as e,a1 as n,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"Linux touch 命令 - 为什么我们需要改变时间戳？ | LCTT x X-CMD","titleTemplate":false,"description":"Linux touch 命令 - 为什么我们需要改变时间戳？ | LCTT (201403) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux touch 命令 - 为什么我们需要改变时间戳？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux touch 命令 - 为什么我们需要改变时间戳？ | LCTT (201403) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201403/Linux touch command - Why do we need to change Timestamp","title":"Linux touch 命令 - 为什么我们需要改变时间戳？","tag":"201403","desc":""},"relativePath":"201403/Linux touch command - Why do we need to change Timestamp.md","filePath":"[post].md"}'),s={name:"201403/Linux touch command - Why do we need to change Timestamp.md"};function d(m,t,u,g,x,_){const o=i("Link");return h(),l("div",null,[t[11]||(t[11]=c(`<h1 id="linux-touch-命令-为什么我们需要改变时间戳" tabindex="-1">Linux touch 命令 - 为什么我们需要改变时间戳？ <a class="header-anchor" href="#linux-touch-命令-为什么我们需要改变时间戳" aria-label="Permalink to “Linux touch 命令 - 为什么我们需要改变时间戳？”">​</a></h1><p>我们可能在 Linux 下运用 touch 命令创建一个空文件。当然我们也可以使用其他命令例如 vi, nano 或是任意一个编辑工具来实现。但是你可能需要更多的步骤来完成操作。其实你要知道 touch 命令的主要功能并不是为了创建一个空文件哦。</p><h3 id="什么是-touch-命令" tabindex="-1">什么是 touch 命令 <a class="header-anchor" href="#什么是-touch-命令" aria-label="Permalink to “什么是 touch 命令”">​</a></h3><p>众所周知，每个文件都被附有时间戳。这个时间戳记包括访问时间和修改时间。而 Touch 命令主要就是用来修改文件的访问时间和修改时间。</p><h3 id="为什么我们需要使用-touch-命令" tabindex="-1">为什么我们需要使用 touch 命令 <a class="header-anchor" href="#为什么我们需要使用-touch-命令" aria-label="Permalink to “为什么我们需要使用 touch 命令”">​</a></h3><p>既然 touch 命令描述的是改变时间戳，那么我们可能会想为什么我们需要去改变时间戳呢?这个问题会引发我们的深思。然而，我想有个理由可以解释为什么我们需要使用它。如果你参加了一个全球范围的开源项目，那么时间戳可能变得很重要。编译源代码文件可能需要同一地区的时间戳。如果未统一，程序可能会编译失败。（译注：有强迫症的同学也很喜欢这个命令——就看不得乱七八糟的时间，;&gt;）</p><h3 id="不带任何选项下运行-touch" tabindex="-1">不带任何选项下运行 touch <a class="header-anchor" href="#不带任何选项下运行-touch" aria-label="Permalink to “不带任何选项下运行 touch”">​</a></h3><p>最简单的使用 touch 命令。只需键入：</p><pre><code>$ touch file_name
</code></pre><p>请观察下面的一张截图。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/touch.png" alt="Touch command"></p><p><strong>File_1.txt</strong>原来的时间戳是 12:42。在我们使用 touch 命令后，它改变为了 17:08。由此看出，默认情况下，touch 会将文件的时间戳改为当前时间。</p><h3 id="只改变访问时间" tabindex="-1">只改变访问时间 <a class="header-anchor" href="#只改变访问时间" aria-label="Permalink to “只改变访问时间”">​</a></h3><p>正如我们之前提到的，每个文件都附有访问时间和修改时间。上面的时间戳是 17:08。我们可以看更多的细节。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/touch_stat.png" alt="Detail timestamp"></p><p>我们发现<strong>访问</strong>时间和<strong>修改</strong>时间的值是相同的都是 17:08:35 ,还有它们属于同一时区 GMT +7。</p><p>如果现在我们要只改变访问时间，我们需要使用<strong>-a</strong>选项。</p><pre><code>$ touch -a file_1.txt
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/touch_a.png" alt="Touch -a option"></p><p>如你所见，<strong>访问时间变为</strong>了 17:51:37 ,但是<strong>修改时间仍为</strong>17:08:35。[译注：原文为 Change time(状态改变时间)应是作者笔误]</p><h3 id="只改变修改时间" tabindex="-1">只改变修改时间 <a class="header-anchor" href="#只改变修改时间" aria-label="Permalink to “只改变修改时间”">​</a></h3><p>我们可以使用<strong>-m</strong>选项来实现。现在我们用<strong>file_2.txt</strong>作个示例。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/touch_stat_file_2.png" alt="File_2.txt detail timestamp"></p><pre><code>$ touch -m file_2.txt
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/touch_m.png" alt="Touch -m option"></p><p>现在<strong>修改时间从 12:42:20 改为了 17:57:20。请注意</strong>,当文件被访问或修改时，状态改变时间域的值总会对其记录。</p><h3 id="更改为自定义时间戳" tabindex="-1">更改为自定义时间戳 <a class="header-anchor" href="#更改为自定义时间戳" aria-label="Permalink to “更改为自定义时间戳”">​</a></h3><p><strong>-a</strong>和<strong>-m</strong>选项都会将文件的时间戳改为现在当前时间。当然我们也可以更改为自定义时间戳。使用<strong>-t</strong>选项实现。</p><p>从上面示例示例中的 file_2.txt，我们看出它的时间戳是：</p><pre><code>访问时间:12:42:20
修改时间:17:57:20
执行日期:2014-01-14
</code></pre><p>假如我们想要将<strong>访问时间和修改时间</strong>改为<strong>2014年1月12日 09:58:27</strong>。我们可以用下列命令来完成：</p><pre><code>$ touch -t 201401120958.27 file_2.txt
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/touch_t.png" alt="Touch using -t option"></p><p><strong>-t</strong> 选项语法组成 :</p><h4 id="cc-yy-mmddhhmm-ss" tabindex="-1">[[CC]YY]MMDDhhmm [.SS] <a class="header-anchor" href="#cc-yy-mmddhhmm-ss" aria-label="Permalink to “[[CC]YY]MMDDhhmm [.SS]”">​</a></h4><pre><code>CC - 年份的前两位 
YY - 年份的后两位 
MM - 月份 [01-12]
DD - 日期 [01-31]
hh - 时 [00-23]
mm - 分 [00-59]
SS - 秒 [00-61]
</code></pre><h3 id="改变日期和时间的另一种方式" tabindex="-1">改变日期和时间的另一种方式 <a class="header-anchor" href="#改变日期和时间的另一种方式" aria-label="Permalink to “改变日期和时间的另一种方式”">​</a></h3><p>如果你觉得<strong>[[CC]YY]MMDDhhmm [.SS]</strong>格式不适合你，我们也可以使用 -d 选项。下面是<strong>-d</strong>选项使用的一个示例。</p><h4 id="更改指定日期" tabindex="-1">更改指定日期 <a class="header-anchor" href="#更改指定日期" aria-label="Permalink to “更改指定日期”">​</a></h4><p>举例来说，我们有个名为 file_3.txt 的文件，它的相关属性在下面的截图中展示了。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/stat_file_3.png" alt="File_3.txt detail timestamp"></p><p>现在<strong>我们要将日期2014年1月14日改为2013年12月20日</strong>。可以使用下列命令：</p><pre><code>$ touch -d &#39;10-December-2013&#39; file_3.txt
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/touch_d_date.png" alt="Change date using -d option"></p><p>不出意料，访问时间和修改时间的日期已经改为了2013年12月10日。</p><h3 id="改变时区" tabindex="-1">改变时区 <a class="header-anchor" href="#改变时区" aria-label="Permalink to “改变时区”">​</a></h3><p>如果我们想改变指定GMT的时间，我们也可以使用<strong>-d</strong>选项。先让file_3.txt 移回当前时间。</p><pre><code>$ touch file_3.txt
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/touch_return_file_3.png" alt="Reset file_3.txt timestamp"></p><p>不难发现 file_3.txt 的时区为 GMT +0700。要改为 GMT3 时区，我们只需要键入如下命令：</p><pre><code>$ touch -d GMT3 file_3.txt
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/touch_gmt3.png" alt="Change into GMT3 timezone"></p><p>好的，现在时间已经改为了 10:00:00 AM。</p><h3 id="结合参数下使用-d选项" tabindex="-1">结合参数下使用-d选项 <a class="header-anchor" href="#结合参数下使用-d选项" aria-label="Permalink to “结合参数下使用-d选项”">​</a></h3><p>还可以用很酷的方式使用<strong>-d</strong>选项。请观察下面的图片。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/01/touch_next_sunday.png" alt="Change date using keyword"></p><p>我们可以将单词 <strong>next Sunday</strong> 和 GMT 3合成一个值，而 touch 命令仍然能识别它。日期已经改为了2014年1月21日，而当前的日期为2014年1月14日。</p><p>还有另一个<strong>-d</strong>选项的示例。 首先，我们要将file3_3.txt重置到当前日期和时间。</p><pre><code>$ touch file_3.txt
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/touch_reset_file_3.png" alt="Reset file_3.txt timestamp"></p><p>然后我们尝试这个命令：</p><pre><code>$ touch -d ‘1 year ago 13:43:07’ file_3.txt
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/touch_d_year_ago.png" alt="Change date using keyword"></p><p>太震撼了，Touch 甚至能识别单词‘<strong>1 year ago</strong>’。现在的日期以及时间已经改为了2013年1月14日,13:43:07。</p><h3 id="创建一个空文件" tabindex="-1">创建一个空文件 <a class="header-anchor" href="#创建一个空文件" aria-label="Permalink to “创建一个空文件”">​</a></h3><p>当你运行 touch 命令目标文件不存在时，touch 会创建一个同名的空文件。</p><pre><code>$ touch file_10.txt
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/touch_file_10.png" alt="Create an empty file"></p><h3 id="同时创建多个文件" tabindex="-1">同时创建多个文件 <a class="header-anchor" href="#同时创建多个文件" aria-label="Permalink to “同时创建多个文件”">​</a></h3><p>你可以用空格将目标文件分割开来，以此来创建多个文件。</p><pre><code>$ touch doc_10.txt doc_20.txt doc_30.txt
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/01/touch_multiple_files.png" alt="Create multiple files"></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>如果你要处理关于文件或目录的时间戳问题，那么 Touch 会对你很有用的。一如既往得你也可以键入<strong>man touch</strong>或<strong>touch --help</strong>来显示帮助页面了解更多细节。</p><hr>`,75)),p("p",null,[t[1]||(t[1]=e("via: ",-1)),n(o,{href:"http://linoxide.com/linux-command/linux-touch-command/"},{default:a(()=>[...t[0]||(t[0]=[e("http://linoxide.com/linux-command/linux-touch-command/",-1)])]),_:1})]),p("p",null,[t[4]||(t[4]=e("译者：",-1)),n(o,{href:"https://github.com/Luoxcat"},{default:a(()=>[...t[2]||(t[2]=[e("Luoxcat",-1)])]),_:1}),t[5]||(t[5]=e(" 校对：",-1)),n(o,{href:"https://github.com/wxy"},{default:a(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[8]||(t[8]=e("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原创翻译，",-1)),n(o,{href:"http://linux.cn/"},{default:a(()=>[...t[7]||(t[7]=[e("Linux中国",-1)])]),_:1}),t[10]||(t[10]=e(" 荣誉推出",-1))])])}const C=r(s,[["render",d]]);export{b as __pageData,C as default};
